package com.amdocs.telecom.report;import com.amdocs.telecom.util.DBConnection;import java.sql.*;import java.io.*;import java.nio.file.*;import java.util.concurrent.*;public class ReportService{private final ExecutorService ex=Executors.newFixedThreadPool(2);public Future<Path> generate(String name){return ex.submit(()->{Files.createDirectories(Paths.get("exports"));Path f=Paths.get("exports",name+"-"+System.currentTimeMillis()+".csv");String sql=sql(name);try(Connection c=DBConnection.getInstance().get();Statement s=c.createStatement();ResultSet r=s.executeQuery(sql);BufferedWriter w=Files.newBufferedWriter(f)){ResultSetMetaData md=r.getMetaData();for(int i=1;i<=md.getColumnCount();i++){if(i>1)w.write(',');w.write(md.getColumnLabel(i));}w.newLine();while(r.next()){for(int i=1;i<=md.getColumnCount();i++){if(i>1)w.write(',');String v=String.valueOf(r.getObject(i));w.write('"'+v.replace("\"","\"\"")+'"');}w.newLine();}}return f;});}private String sql(String n){if("sla-compliance".equals(n))return "SELECT sla_status,COUNT(*) total FROM v_ticket_sla GROUP BY sla_status";if("engineer-performance".equals(n))return "SELECT e.engineer_id,e.engineer_name,e.active_ticket_count,COUNT(t.ticket_id) assigned FROM network_engineers e LEFT JOIN trouble_tickets t ON e.engineer_id=t.assigned_engineer_id GROUP BY e.engineer_id,e.engineer_name,e.active_ticket_count";if("incident-category".equals(n))return "SELECT category,COUNT(*) total FROM trouble_tickets GROUP BY category ORDER BY total DESC";if("regional-incident".equals(n))return "SELECT e.region,COUNT(t.ticket_id) total FROM network_engineers e LEFT JOIN trouble_tickets t ON e.engineer_id=t.assigned_engineer_id GROUP BY e.region";if("average-resolution".equals(n))return "SELECT AVG(DATEDIFF('MINUTE',created_date,resolution_date))/60.0 average_resolution_hours FROM trouble_tickets WHERE resolution_date IS NOT NULL";if("critical-incident".equals(n))return "SELECT ticket_number,status,created_date,sla_deadline FROM trouble_tickets WHERE priority='CRITICAL'";return "SELECT status,priority,COUNT(*) total FROM trouble_tickets GROUP BY status,priority";}}
